  assert.equal(row.contrastFailures, 0, `${label}: token contrast`);
  assert.equal(row.smallTargets, 0, `${label}: targets under the 24 px floor`);
  assert.equal(row.denseUnder, 0, `${label}: dense controls under 32 px`);
  assert.equal(row.overflow, false, `${label}: horizontal page overflow`);
  /* the thick-client contract (UI-H2): the window never scrolls, the toolbar is one 44 px row that never overflows, every dock scrolls internally */
  assert.equal(row.shell.windowScroll, false, `${label}: the window must not scroll`);
  assert.equal(row.shell.toolbarOverflow, false, `${label}: the toolbar must not overflow its row`);
  assert(row.shell.toolbarRows <= 44, `${label}: toolbar height ${row.shell.toolbarRows} > 44`);
  assert.equal(row.shell.docksScrollInternally, true, `${label}: docks must scroll internally`);
  assert.equal(!!row.shell.statusOverflow, false, `${label}: the status bar must not clip`); assert.equal(!!row.shell.paramrowOverflow, false, `${label}: the parameter row must not clip`); assert.equal(!!row.shell.doctabsOverflow, false, `${label}: the document-tab row must not clip`);
