  const gapToCurve = (ch, i) => page.evaluate(([ch, i]) => { const P = M.preview && M.preview.ch === ch ? M.preview.P : M.cv[ch]; const U = Uof(P); let min = 1e9; for (let k = 0; k <= 800; k++) { const q = BS.evalCurve(P, CVS.deg, U, k / 800); min = Math.min(min, Math.hypot(q[0] - P[i][0], q[1] - P[i][1])); } return min; }, [ch, i]);
